<?php
namespace backend\controllers; use backend\models\Company; use backend\models\CompanySearch; use Yii; use yii\filters\AccessControl; use yii\filters\VerbFilter; use yii\web\Controller; use yii\web\NotFoundHttpException;
class CompanyController extends Controller { public function behaviors() { return ['access' => ['class' => AccessControl::class, 'rules' => [['allow' => true, 'roles' => ['@']]]], 'verbs' => ['class' => VerbFilter::class, 'actions' => ['delete' => ['POST']]]]; } public function actionIndex() { $searchModel = new CompanySearch(); $dataProvider = $searchModel->search(Yii::$app->request->queryParams); return $this->render('index', compact('searchModel', 'dataProvider')); } public function actionCreate() { $model = new Company(); if ($model->load(Yii::$app->request->post()) && $model->save()) return $this->redirect(['view', 'id' => $model->id]); return $this->render('create', compact('model')); } public function actionView($id) { $model=$this->findModel($id); return $this->render('view', compact('model')); } public function actionUpdate($id) { $model=$this->findModel($id); if ($model->load(Yii::$app->request->post()) && $model->save()) return $this->redirect(['view','id'=>$model->id]); return $this->render('update',compact('model')); } public function actionDelete($id) { $this->findModel($id)->delete(); return $this->redirect(['index']); } protected function findModel($id) { if (($model=Company::findOne($id))!==null) return $model; throw new NotFoundHttpException('Perusahaan tidak ditemukan.'); } }
